class Solution {
public:
    vector<int> constructArray(int n, int k) {
        vector<int> res;
        int left = 1, right = k + 1;
        while (left <= right) {
            res.push_back(left++);
            if (left <= right) {
                res.push_back(right--);
            }
        }
        for (int i = k + 2; i <= n; i++) {
            res.push_back(i);
        }
        return res;
    }
};

class Solution {
    public int[] constructArray(int n, int k) {
        int[] res = new int[n];
        int left = 1, right = k + 1;
        int idx = 0;
        while (left <= right) {
            res[idx++] = left++;
            if (left <= right) {
                res[idx++] = right--;
            }
        }
        for (int i = k + 2; i <= n; i++) {
            res[idx++] = i;
        }
        return res;
    }
}

var constructArray = function(n, k) {
    const res = [];
    let left = 1, right = k + 1;
    while (left <= right) {
        res.push(left++);
        if (left <= right) {
            res.push(right--);
        }
    }
    for (let i = k + 2; i <= n; i++) {
        res.push(i);
    }
    return res;
